import React from "react";
export default function Subscription() {
    return(
        <div className= "subscribe">
         <h4>
            JioHotstar subscription plans start from a nominal Rs. 149. The plans are categorised into three subscription options: Mobile, Super, and Premium. Each plan caters to different user needs, ranging from budget-friendly options to high-quality, multi-device streaming.
         </h4>
           <img src="https://prod4-sprcdn-assets.sprinklr.com/200030/5256cb11-e64a-4d50-a224-be833308798e-1956696302.jpg" />
        </div>
    )
}
